using System;
using System.IO;
using System.IO.Compression;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine("=== BUILD ERRORS ===");
foreach (var e in errors)
{
    Console.WriteLine($"  Project: {e.ProjectFile}");
    Console.WriteLine($"  File:    {e.File}");
    Console.WriteLine($"  Line:    {e.LineNumber}");
    Console.WriteLine($"  Code:    {e.Code}");
    Console.WriteLine($"  Text:    {e.Text}");
    Console.WriteLine();
}

Console.WriteLine("=== BUILD WARNINGS ===");
foreach (var w in warnings)
{
    Console.WriteLine($"  Project: {w.ProjectFile}");
    Console.WriteLine($"  Code:    {w.Code}");
    Console.WriteLine($"  Text:    {w.Text}");
    Console.WriteLine();
}

Console.WriteLine("=== PROJECT STRUCTURE ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"  Project: {p.Name} -> {p.ProjectFile}");
}

// Extract embedded source files from the binlog
Console.WriteLine("\n=== EMBEDDED FILES ===");
if (build.SourceFilesArchive != null)
{
    using var ms = new MemoryStream(build.SourceFilesArchive);
    using var zip = new ZipArchive(ms, ZipArchiveMode.Read);
    foreach (var entry in zip.Entries)
    {
        Console.WriteLine($"\n--- FILE: {entry.FullName} ---");
        using var reader = new StreamReader(entry.Open());
        Console.WriteLine(reader.ReadToEnd());
    }
}
